// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        // owner is address(0) initially; transfer ownership to a fresh address != actor
        address newOwner = address(uint160(uint256(uint160(actor)) ^ 1));
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        // Rule: for any caller that is not the current owner, owned() must revert.
        assertTrue(actor == c.owner() ? ok : !ok);
    }
}
